namespace MyApp.Evals.Tests;

internal static class RepoRoot
{
    public static string Find()
    {
        var dir = AppContext.BaseDirectory;
        while (dir is not null)
        {
            if (File.Exists(Path.Combine(dir, "MyApp.slnx")))
                return dir;
            dir = Directory.GetParent(dir)?.FullName;
        }

        // Fallback: walk up from the current directory
        dir = Directory.GetCurrentDirectory();
        while (dir is not null)
        {
            if (File.Exists(Path.Combine(dir, "MyApp.slnx")))
                return dir;
            dir = Directory.GetParent(dir)?.FullName;
        }

        throw new InvalidOperationException(
            "Could not find repository root (no MyApp.slnx found in parent directories).");
    }
}

namespace MyApp.Evals.Tests;

/// <summary>
/// Resolves the same IChatClient the app uses, by building a minimal
/// host that mirrors the app's DI registration.
/// Detected: AddAzureOpenAIChatClient("chat", "gpt-4o-mini") at AppHost.cs:2
/// </summary>
internal static class AgentChatClientFactory
{
    public static IChatClient Create()
    {
        var builder = Host.CreateApplicationBuilder();

        // In test hosts (dotnet test), the entry assembly is testhost.exe so
        // user-secrets are NOT auto-loaded. Add them explicitly.
        builder.Configuration.AddUserSecrets(typeof(AgentChatClientFactory).Assembly, optional: true);

        builder.Services.AddAzureOpenAIChatClient("chat", "gpt-4o-mini");
        var host = builder.Build();
        try
        {
            return host.Services.GetRequiredService<IChatClient>();
        }
        catch (InvalidOperationException ex)
        {
            throw new InvalidOperationException(
                "EVAL_USE_REAL_AGENT=1 but IChatClient could not be resolved. " +
                "The detected registration (AddAzureOpenAIChatClient) reads connection " +
                "string \"chat\" from configuration. Aspire's AppHost populates this at runtime, " +
                "but `dotnet test` runs standalone. Wire one of:\n" +
                "  # Key-based auth (only if the resource has it enabled):\n" +
                "  dotnet user-secrets set \"ConnectionStrings:chat\" " +
                "\"Endpoint=https://<host>.services.ai.azure.com/models;Key=<key>;DeploymentId=chat\" --project MyApp.Evals.Tests\n" +
                "  # Entra-ID auth (DefaultAzureCredential — works when key auth is disabled):\n" +
                "  dotnet user-secrets set \"ConnectionStrings:chat\" " +
                "\"Endpoint=https://<host>.services.ai.azure.com/models;DeploymentId=chat\" --project MyApp.Evals.Tests\n" +
                "Note: the hostname strips dashes from the resource name " +
                "(resource `foundry-abc` -> host `foundryabc.services.ai.azure.com`).",
                ex);
        }
    }

    public static IChatClient Create(IDictionary<string, string>? modelOverrides)
    {
        if (modelOverrides is null || modelOverrides.Count == 0)
            return Create();

        var builder = Host.CreateApplicationBuilder();
        builder.Configuration.AddUserSecrets(typeof(AgentChatClientFactory).Assembly, optional: true);

        // Use the first override's model for the chat client
        var model = modelOverrides.Values.FirstOrDefault() ?? "gpt-4o-mini";
        builder.Services.AddAzureOpenAIChatClient("chat", model);
        var host = builder.Build();
        return host.Services.GetRequiredService<IChatClient>();
    }
}

namespace MyApp.Evals.Tests;

/// <summary>
/// Stub IChatClient used when EVAL_USE_REAL_AGENT is unset.
/// Returns a deterministic response for eval scaffolding/testing.
/// </summary>
internal sealed class StubChatClient : IChatClient
{
    public Task<ChatResponse> GetResponseAsync(
        IEnumerable<ChatMessage> messages,
        ChatOptions? options = null,
        CancellationToken cancellationToken = default)
    {
        var userMessage = messages.LastOrDefault(m => m.Role == ChatRole.User)?.Text ?? "";
        var stubResponse = $"This is a stub response to: {userMessage}";

        return Task.FromResult(new ChatResponse(
            [new ChatMessage(ChatRole.Assistant, stubResponse)])
        {
            ModelId = "stub",
            Usage = new UsageDetails
            {
                InputTokenCount = userMessage.Split(' ').Length,
                OutputTokenCount = stubResponse.Split(' ').Length,
            },
        });
    }

    public IAsyncEnumerable<ChatResponseUpdate> GetStreamingResponseAsync(
        IEnumerable<ChatMessage> messages,
        ChatOptions? options = null,
        CancellationToken cancellationToken = default) =>
        throw new NotSupportedException("Streaming not supported in stub.");

    public object? GetService(Type serviceType, object? serviceKey = null) => null;

    public void Dispose() { }
}

namespace MyApp.Evals.Tests;

internal static class Wire
{
    public static IChatClient ResolveAgentClient() =>
        EvalEnv.UseRealAgent ? AgentChatClientFactory.Create() : new StubChatClient();

    public static IChatClient ResolveAgentClient(IDictionary<string, string>? modelOverrides) =>
        EvalEnv.UseRealAgent ? AgentChatClientFactory.Create(modelOverrides) : new StubChatClient();

    public static IChatClient ResolveJudgeClient(IChatClient agentClient)
    {
        var judgeOverride = Environment.GetEnvironmentVariable("EVAL_JUDGE_DEPLOYMENT_NAME");
        if (!string.IsNullOrEmpty(judgeOverride))
        {
            // Use a separate deployment for judging
            return AgentChatClientFactory.Create(new Dictionary<string, string>
            {
                ["judge"] = judgeOverride
            });
        }

        // Default: same client for agent and judge
        return agentClient;
    }
}

