namespace MyApp.Evals.Tests;

/// <summary>
/// Resolves the same IChatClient the app uses.
/// Detected: AddAzureOpenAIChatClient("chat", "gpt-4o-mini") at AppHost.cs:2
///
/// The AppHost uses Aspire orchestration to wire the client. For standalone
/// test runs, wire a connection string via user-secrets (see README below).
/// </summary>
internal static class AgentChatClientFactory
{
    public static IChatClient Create()
    {
        var builder = Host.CreateApplicationBuilder();

        // In test hosts (dotnet test), the entry assembly is testhost.exe so
        // user-secrets are NOT auto-loaded. Add them explicitly.
        builder.Configuration.AddUserSecrets(typeof(AgentChatClientFactory).Assembly, optional: true);

        var connectionString = builder.Configuration.GetConnectionString("chat");
        if (string.IsNullOrEmpty(connectionString))
        {
            throw new InvalidOperationException(
                "EVAL_USE_REAL_AGENT=1 but ConnectionStrings:chat is not configured. " +
                "The detected registration (AddAzureOpenAIChatClient) reads connection " +
                "string \"chat\" from configuration. Aspire's AppHost populates this at runtime, " +
                "but `dotnet test` runs standalone. Wire one of:\n" +
                "  dotnet user-secrets init --project MyApp.Evals.Tests\n" +
                "  # Key-based auth (only if the resource has it enabled):\n" +
                "  dotnet user-secrets set \"ConnectionStrings:chat\" " +
                "\"Endpoint=https://<host>.services.ai.azure.com/models;Key=<key>;DeploymentId=chat\" --project MyApp.Evals.Tests\n" +
                "  # Entra-ID auth (DefaultAzureCredential — works when key auth is disabled):\n" +
                "  dotnet user-secrets set \"ConnectionStrings:chat\" " +
                "\"Endpoint=https://<host>.services.ai.azure.com/models;DeploymentId=chat\" --project MyApp.Evals.Tests\n" +
                "Note: the hostname strips dashes from the resource name " +
                "(resource `foundry-abc` -> host `foundryabc.services.ai.azure.com`).");
        }

        // Build an IChatClient from the connection string.
        // The user wires the real Azure OpenAI endpoint via user-secrets.
        builder.Services.AddChatClient(sp =>
            new Azure.AI.Inference.ChatCompletionsClient(
                new Uri(ParseEndpoint(connectionString)),
                new Azure.AzureKeyCredential(ParseKey(connectionString) ?? "placeholder"))
            .AsIChatClient(ParseDeploymentId(connectionString) ?? "chat"));

        var host = builder.Build();
        return host.Services.GetRequiredService<IChatClient>();
    }

    public static IChatClient Create(IDictionary<string, string>? modelOverrides) => Create();

    private static string ParseEndpoint(string cs) =>
        cs.Split(';').FirstOrDefault(s => s.StartsWith("Endpoint=", StringComparison.OrdinalIgnoreCase))
          ?.Substring("Endpoint=".Length) ?? cs;

    private static string? ParseKey(string cs) =>
        cs.Split(';').FirstOrDefault(s => s.StartsWith("Key=", StringComparison.OrdinalIgnoreCase))
          ?.Substring("Key=".Length);

    private static string? ParseDeploymentId(string cs) =>
        cs.Split(';').FirstOrDefault(s => s.StartsWith("DeploymentId=", StringComparison.OrdinalIgnoreCase))
          ?.Substring("DeploymentId=".Length);
}

