            .AsIChatClient(ParseDeploymentId(connectionString) ?? "chat"));

        var host = builder.Build();
        return host.Services.GetRequiredService<IChatClient>();
    }

    public static IChatClient Create(IDictionary<string, string>? modelOverrides) => Create();

    private static string ParseEndpoint(string cs) =>
        cs.Split(';').FirstOrDefault(s => s.StartsWith("Endpoint=", StringComparison.OrdinalIgnoreCase))
          ?.Substring("Endpoint=".Length) ?? cs;

    private static string? ParseKey(string cs) =>
        cs.Split(';').FirstOrDefault(s => s.StartsWith("Key=", StringComparison.OrdinalIgnoreCase))
          ?.Substring("Key=".Length);

    private static string? ParseDeploymentId(string cs) =>
        cs.Split(';').FirstOrDefault(s => s.StartsWith("DeploymentId=", StringComparison.OrdinalIgnoreCase))
          ?.Substring("DeploymentId=".Length);
}

