namespace MyApp.Evals.Tests;

internal sealed class WordCountEvaluator : IEvaluator
{
    public string Name => "Words";

    public IReadOnlyCollection<string> EvaluationMetricNames => [Name];

    public ValueTask<EvaluationResult> EvaluateAsync(
        IEnumerable<ChatMessage> messages,
        ChatResponse modelResponse,
        ChatConfiguration? chatConfiguration = null,
        IEnumerable<EvaluationContext>? additionalContext = null,
        CancellationToken cancellationToken = default)
    {
        var text = modelResponse.Text ?? string.Empty;
        var wordCount = text.Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries).Length;

        var (rating, reason) = wordCount switch
        {
            < 5 => (EvaluationRating.Poor, "Response too short or empty"),
            <= 500 => (EvaluationRating.Good, "Response length within expected range"),
            _ => (EvaluationRating.Average, "Response unusually long"),
        };

        var metric = new NumericMetric(Name, wordCount);
        metric.Interpretation = new EvaluationMetricInterpretation(rating, failed: false, reason);

        var result = new EvaluationResult();
        result.Metrics[Name] = metric;
        return ValueTask.FromResult(result);
    }
}

